// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Liveness and readiness of the server and its database
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// API requests (access log), newest first
	// (GET /v1/admin/access)
	ListAdminAccess(w http.ResponseWriter, r *http.Request, params ListAdminAccessParams)
	// Audit events, newest first
	// (GET /v1/admin/audit)
	ListAdminAudit(w http.ResponseWriter, r *http.Request, params ListAdminAuditParams)
	// Backup status, channel check and recent runs
	// (GET /v1/admin/backups)
	GetAdminBackups(w http.ResponseWriter, r *http.Request)
	// Back up now
	// (POST /v1/admin/backups/run)
	RunAdminBackup(w http.ResponseWriter, r *http.Request)
	// Send a test message to the backup channel
	// (POST /v1/admin/backups/test)
	TestAdminBackupChannel(w http.ResponseWriter, r *http.Request)
	// Catalog enrichment state, runs and items to review
	// (GET /v1/admin/catalog)
	GetAdminCatalog(w http.ResponseWriter, r *http.Request)
	// Put failed products back in the enrichment queue
	// (POST /v1/admin/catalog/enrich/retry-failed)
	RetryAdminCatalogFailed(w http.ResponseWriter, r *http.Request)
	// Run enrichment now
	// (POST /v1/admin/catalog/enrich/run)
	RunAdminCatalogEnrich(w http.ResponseWriter, r *http.Request)
	// Delete an enricher-created ingredient
	// (DELETE /v1/admin/catalog/ingredients/{id})
	DeleteAdminIngredient(w http.ResponseWriter, r *http.Request, id IngredientID)
	// Merge an enricher-created ingredient into another
	// (POST /v1/admin/catalog/ingredients/{id}/merge)
	MergeAdminIngredient(w http.ResponseWriter, r *http.Request, id IngredientID)
	// Make an enricher-created ingredient global
	// (POST /v1/admin/catalog/ingredients/{id}/promote)
	PromoteAdminIngredient(w http.ResponseWriter, r *http.Request, id IngredientID)
	// Every household
	// (GET /v1/admin/households)
	AdminListHouseholds(w http.ResponseWriter, r *http.Request)
	// Background jobs, newest first
	// (GET /v1/admin/jobs)
	ListAdminJobs(w http.ResponseWriter, r *http.Request, params ListAdminJobsParams)
	// Cancel a job
	// (POST /v1/admin/jobs/{id}/cancel)
	CancelAdminJob(w http.ResponseWriter, r *http.Request, id AdminJobID)
	// Run a job again now
	// (POST /v1/admin/jobs/{id}/retry)
	RetryAdminJob(w http.ResponseWriter, r *http.Request, id AdminJobID)
	// Remove a provider's API key
	// (DELETE /v1/admin/llm/providers/{id}/key)
	DeleteLLMProviderKey(w http.ResponseWriter, r *http.Request, id string)
	// Store a provider's API key (write-only, encrypted at rest)
	// (PUT /v1/admin/llm/providers/{id}/key)
	SetLLMProviderKey(w http.ResponseWriter, r *http.Request, id string)
	// LLM providers, their state and today's quota
	// (GET /v1/admin/llm/status)
	GetLLMStatus(w http.ResponseWriter, r *http.Request)
	// Send a test prompt through the gateway
	// (POST /v1/admin/llm/test)
	TestLLMPrompt(w http.ResponseWriter, r *http.Request)
	// LLM usage per day, provider and feature
	// (GET /v1/admin/llm/usage)
	GetLLMUsage(w http.ResponseWriter, r *http.Request, params GetLLMUsageParams)
	// Application log lines, newest first
	// (GET /v1/admin/logs)
	ListAdminLogs(w http.ResponseWriter, r *http.Request, params ListAdminLogsParams)
	// System state at a glance
	// (GET /v1/admin/overview)
	GetAdminOverview(w http.ResponseWriter, r *http.Request)
	// Sign out any session
	// (DELETE /v1/admin/sessions/{sessionId})
	AdminRevokeSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// Every runtime setting and feature flag
	// (GET /v1/admin/settings)
	ListAdminSettings(w http.ResponseWriter, r *http.Request)
	// Reset a setting to its default
	// (DELETE /v1/admin/settings/{key})
	ResetAdminSetting(w http.ResponseWriter, r *http.Request, key string)
	// Change a setting
	// (PUT /v1/admin/settings/{key})
	PutAdminSetting(w http.ResponseWriter, r *http.Request, key string)
	// Telegram bot status for Admin → Settings
	// (GET /v1/admin/telegram)
	GetAdminTelegram(w http.ResponseWriter, r *http.Request)
	// Users, newest first
	// (GET /v1/admin/users)
	AdminListUsers(w http.ResponseWriter, r *http.Request, params AdminListUsersParams)
	// Enable, disable or change the system role of an approved user
	// (PATCH /v1/admin/users/{userId})
	AdminUpdateUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// Approve a pending user
	// (POST /v1/admin/users/{userId}/approve)
	AdminApproveUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// Reject a pending user (disables them and signs them out)
	// (POST /v1/admin/users/{userId}/reject)
	AdminRejectUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// A user's signed-in sessions
	// (GET /v1/admin/users/{userId}/sessions)
	AdminListUserSessions(w http.ResponseWriter, r *http.Request, userId UserId)
	// Start a passkey sign-in
	// (POST /v1/auth/login/begin)
	BeginLogin(w http.ResponseWriter, r *http.Request)
	// Verify the passkey and sign in
	// (POST /v1/auth/login/finish)
	FinishLogin(w http.ResponseWriter, r *http.Request)
	// Sign out this session
	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// What a text matches
	// (GET /v1/catalog/match)
	MatchCatalog(w http.ResponseWriter, r *http.Request, params MatchCatalogParams)
	// Apply a batch of offline commands
	// (POST /v1/commands)
	ApplyCommands(w http.ResponseWriter, r *http.Request)
	// Invites of a household
	// (GET /v1/invites)
	ListInvites(w http.ResponseWriter, r *http.Request, params ListInvitesParams)
	// Create a single-use invite link
	// (POST /v1/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request)
	// Start creating an account from an invite (passkey enrolment)
	// (POST /v1/invites/accept/begin)
	BeginAcceptInvite(w http.ResponseWriter, r *http.Request)
	// Create the account (pending approval by default) and sign in
	// (POST /v1/invites/accept/finish)
	FinishAcceptInvite(w http.ResponseWriter, r *http.Request)
	// What an invite code joins (household, role, expiry)
	// (POST /v1/invites/inspect)
	InspectInvite(w http.ResponseWriter, r *http.Request)
	// Join another household with an invite, as a signed-in user
	// (POST /v1/invites/join)
	JoinWithInvite(w http.ResponseWriter, r *http.Request)
	// Revoke a pending invite
	// (DELETE /v1/invites/{inviteId})
	RevokeInvite(w http.ResponseWriter, r *http.Request, inviteId openapi_types.UUID)
	// The signed-in user, their households and the active one
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// Change the display name
	// (PATCH /v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// Make another of the user's households active for this session
	// (PUT /v1/me/household)
	SwitchHousehold(w http.ResponseWriter, r *http.Request)
	// The user's passkeys
	// (GET /v1/me/passkeys)
	ListMyPasskeys(w http.ResponseWriter, r *http.Request)
	// Start adding a passkey
	// (POST /v1/me/passkeys/begin)
	BeginAddPasskey(w http.ResponseWriter, r *http.Request)
	// Store the new passkey
	// (POST /v1/me/passkeys/finish)
	FinishAddPasskey(w http.ResponseWriter, r *http.Request)
	// Remove a passkey (not the last one)
	// (DELETE /v1/me/passkeys/{passkeyId})
	RemoveMyPasskey(w http.ResponseWriter, r *http.Request, passkeyId string)
	// The user's signed-in sessions
	// (GET /v1/me/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// Sign out one of the user's sessions
	// (DELETE /v1/me/sessions/{sessionId})
	RevokeMySession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// Build and contract versions, and the server clock
	// (GET /v1/meta)
	GetMeta(w http.ResponseWriter, r *http.Request)
	// The user's inbox, newest first, with the unread count
	// (GET /v1/notifications)
	ListNotifications(w http.ResponseWriter, r *http.Request, params ListNotificationsParams)
	// The user's alert preferences (their own, else the system defaults)
	// (GET /v1/notifications/preferences)
	GetNotificationPreferences(w http.ResponseWriter, r *http.Request)
	// Change the user's alert preferences
	// (PUT /v1/notifications/preferences)
	SetNotificationPreferences(w http.ResponseWriter, r *http.Request)
	// Mark notifications read
	// (POST /v1/notifications/read)
	MarkNotificationsRead(w http.ResponseWriter, r *http.Request)
	// Disconnect Telegram
	// (DELETE /v1/notifications/telegram)
	DisconnectTelegram(w http.ResponseWriter, r *http.Request)
	// Whether the bot is available and this user is connected
	// (GET /v1/notifications/telegram)
	GetTelegramConnection(w http.ResponseWriter, r *http.Request)
	// Start connecting Telegram
	// (POST /v1/notifications/telegram/link)
	StartTelegramLink(w http.ResponseWriter, r *http.Request)
	// Send a test message to the user's Telegram
	// (POST /v1/notifications/telegram/test)
	TestTelegramConnection(w http.ResponseWriter, r *http.Request)
	// Whether the first admin still has to be claimed
	// (GET /v1/setup)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// Check the admin setup token and start enrolling the first admin's passkey
	// (POST /v1/setup/begin)
	BeginSetup(w http.ResponseWriter, r *http.Request)
	// Create the first admin and household, and sign in
	// (POST /v1/setup/finish)
	FinishSetup(w http.ResponseWriter, r *http.Request)
	// Changes to the household's synced rows since a cursor
	// (GET /v1/sync)
	GetSync(w http.ResponseWriter, r *http.Request, params GetSyncParams)
	// Server-sent events that say "something changed, pull now"
	// (GET /v1/sync/events)
	GetSyncEvents(w http.ResponseWriter, r *http.Request)
}

