// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Liveness and readiness of the server and its database
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// API requests (access log), newest first
	// (GET /v1/admin/access)
	ListAdminAccess(ctx context.Context, request ListAdminAccessRequestObject) (ListAdminAccessResponseObject, error)
	// Audit events, newest first
	// (GET /v1/admin/audit)
	ListAdminAudit(ctx context.Context, request ListAdminAuditRequestObject) (ListAdminAuditResponseObject, error)
	// Backup status, channel check and recent runs
	// (GET /v1/admin/backups)
	GetAdminBackups(ctx context.Context, request GetAdminBackupsRequestObject) (GetAdminBackupsResponseObject, error)
	// Back up now
	// (POST /v1/admin/backups/run)
	RunAdminBackup(ctx context.Context, request RunAdminBackupRequestObject) (RunAdminBackupResponseObject, error)
	// Send a test message to the backup channel
	// (POST /v1/admin/backups/test)
	TestAdminBackupChannel(ctx context.Context, request TestAdminBackupChannelRequestObject) (TestAdminBackupChannelResponseObject, error)
	// Catalog enrichment state, runs and items to review
	// (GET /v1/admin/catalog)
	GetAdminCatalog(ctx context.Context, request GetAdminCatalogRequestObject) (GetAdminCatalogResponseObject, error)
	// Put failed products back in the enrichment queue
	// (POST /v1/admin/catalog/enrich/retry-failed)
	RetryAdminCatalogFailed(ctx context.Context, request RetryAdminCatalogFailedRequestObject) (RetryAdminCatalogFailedResponseObject, error)
	// Run enrichment now
	// (POST /v1/admin/catalog/enrich/run)
	RunAdminCatalogEnrich(ctx context.Context, request RunAdminCatalogEnrichRequestObject) (RunAdminCatalogEnrichResponseObject, error)
	// Delete an enricher-created ingredient
	// (DELETE /v1/admin/catalog/ingredients/{id})
	DeleteAdminIngredient(ctx context.Context, request DeleteAdminIngredientRequestObject) (DeleteAdminIngredientResponseObject, error)
	// Merge an enricher-created ingredient into another
	// (POST /v1/admin/catalog/ingredients/{id}/merge)
	MergeAdminIngredient(ctx context.Context, request MergeAdminIngredientRequestObject) (MergeAdminIngredientResponseObject, error)
	// Make an enricher-created ingredient global
	// (POST /v1/admin/catalog/ingredients/{id}/promote)
	PromoteAdminIngredient(ctx context.Context, request PromoteAdminIngredientRequestObject) (PromoteAdminIngredientResponseObject, error)
	// Every household
	// (GET /v1/admin/households)
	AdminListHouseholds(ctx context.Context, request AdminListHouseholdsRequestObject) (AdminListHouseholdsResponseObject, error)
	// Background jobs, newest first
	// (GET /v1/admin/jobs)
	ListAdminJobs(ctx context.Context, request ListAdminJobsRequestObject) (ListAdminJobsResponseObject, error)
	// Cancel a job
	// (POST /v1/admin/jobs/{id}/cancel)
	CancelAdminJob(ctx context.Context, request CancelAdminJobRequestObject) (CancelAdminJobResponseObject, error)
	// Run a job again now
	// (POST /v1/admin/jobs/{id}/retry)
	RetryAdminJob(ctx context.Context, request RetryAdminJobRequestObject) (RetryAdminJobResponseObject, error)
	// Remove a provider's API key
	// (DELETE /v1/admin/llm/providers/{id}/key)
	DeleteLLMProviderKey(ctx context.Context, request DeleteLLMProviderKeyRequestObject) (DeleteLLMProviderKeyResponseObject, error)
	// Store a provider's API key (write-only, encrypted at rest)
	// (PUT /v1/admin/llm/providers/{id}/key)
	SetLLMProviderKey(ctx context.Context, request SetLLMProviderKeyRequestObject) (SetLLMProviderKeyResponseObject, error)
	// LLM providers, their state and today's quota
	// (GET /v1/admin/llm/status)
	GetLLMStatus(ctx context.Context, request GetLLMStatusRequestObject) (GetLLMStatusResponseObject, error)
	// Send a test prompt through the gateway
	// (POST /v1/admin/llm/test)
	TestLLMPrompt(ctx context.Context, request TestLLMPromptRequestObject) (TestLLMPromptResponseObject, error)
	// LLM usage per day, provider and feature
	// (GET /v1/admin/llm/usage)
	GetLLMUsage(ctx context.Context, request GetLLMUsageRequestObject) (GetLLMUsageResponseObject, error)
	// Application log lines, newest first
	// (GET /v1/admin/logs)
	ListAdminLogs(ctx context.Context, request ListAdminLogsRequestObject) (ListAdminLogsResponseObject, error)
	// System state at a glance
	// (GET /v1/admin/overview)
	GetAdminOverview(ctx context.Context, request GetAdminOverviewRequestObject) (GetAdminOverviewResponseObject, error)
	// Sign out any session
	// (DELETE /v1/admin/sessions/{sessionId})
	AdminRevokeSession(ctx context.Context, request AdminRevokeSessionRequestObject) (AdminRevokeSessionResponseObject, error)
	// Every runtime setting and feature flag
	// (GET /v1/admin/settings)
	ListAdminSettings(ctx context.Context, request ListAdminSettingsRequestObject) (ListAdminSettingsResponseObject, error)
	// Reset a setting to its default
	// (DELETE /v1/admin/settings/{key})
	ResetAdminSetting(ctx context.Context, request ResetAdminSettingRequestObject) (ResetAdminSettingResponseObject, error)
	// Change a setting
	// (PUT /v1/admin/settings/{key})
	PutAdminSetting(ctx context.Context, request PutAdminSettingRequestObject) (PutAdminSettingResponseObject, error)
	// Telegram bot status for Admin → Settings
	// (GET /v1/admin/telegram)
	GetAdminTelegram(ctx context.Context, request GetAdminTelegramRequestObject) (GetAdminTelegramResponseObject, error)
	// Users, newest first
	// (GET /v1/admin/users)
	AdminListUsers(ctx context.Context, request AdminListUsersRequestObject) (AdminListUsersResponseObject, error)
	// Enable, disable or change the system role of an approved user
	// (PATCH /v1/admin/users/{userId})
	AdminUpdateUser(ctx context.Context, request AdminUpdateUserRequestObject) (AdminUpdateUserResponseObject, error)
	// Approve a pending user
	// (POST /v1/admin/users/{userId}/approve)
	AdminApproveUser(ctx context.Context, request AdminApproveUserRequestObject) (AdminApproveUserResponseObject, error)
	// Reject a pending user (disables them and signs them out)
	// (POST /v1/admin/users/{userId}/reject)
	AdminRejectUser(ctx context.Context, request AdminRejectUserRequestObject) (AdminRejectUserResponseObject, error)
	// A user's signed-in sessions
	// (GET /v1/admin/users/{userId}/sessions)
	AdminListUserSessions(ctx context.Context, request AdminListUserSessionsRequestObject) (AdminListUserSessionsResponseObject, error)
	// Start a passkey sign-in
	// (POST /v1/auth/login/begin)
	BeginLogin(ctx context.Context, request BeginLoginRequestObject) (BeginLoginResponseObject, error)
	// Verify the passkey and sign in
	// (POST /v1/auth/login/finish)
	FinishLogin(ctx context.Context, request FinishLoginRequestObject) (FinishLoginResponseObject, error)
	// Sign out this session
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// What a text matches
	// (GET /v1/catalog/match)
	MatchCatalog(ctx context.Context, request MatchCatalogRequestObject) (MatchCatalogResponseObject, error)
	// Apply a batch of offline commands
	// (POST /v1/commands)
	ApplyCommands(ctx context.Context, request ApplyCommandsRequestObject) (ApplyCommandsResponseObject, error)
	// Invites of a household
	// (GET /v1/invites)
	ListInvites(ctx context.Context, request ListInvitesRequestObject) (ListInvitesResponseObject, error)
	// Create a single-use invite link
	// (POST /v1/invites)
	CreateInvite(ctx context.Context, request CreateInviteRequestObject) (CreateInviteResponseObject, error)
	// Start creating an account from an invite (passkey enrolment)
	// (POST /v1/invites/accept/begin)
	BeginAcceptInvite(ctx context.Context, request BeginAcceptInviteRequestObject) (BeginAcceptInviteResponseObject, error)
	// Create the account (pending approval by default) and sign in
	// (POST /v1/invites/accept/finish)
	FinishAcceptInvite(ctx context.Context, request FinishAcceptInviteRequestObject) (FinishAcceptInviteResponseObject, error)
	// What an invite code joins (household, role, expiry)
	// (POST /v1/invites/inspect)
	InspectInvite(ctx context.Context, request InspectInviteRequestObject) (InspectInviteResponseObject, error)
	// Join another household with an invite, as a signed-in user
	// (POST /v1/invites/join)
	JoinWithInvite(ctx context.Context, request JoinWithInviteRequestObject) (JoinWithInviteResponseObject, error)
	// Revoke a pending invite
	// (DELETE /v1/invites/{inviteId})
	RevokeInvite(ctx context.Context, request RevokeInviteRequestObject) (RevokeInviteResponseObject, error)
	// The signed-in user, their households and the active one
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Change the display name
	// (PATCH /v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// Make another of the user's households active for this session
	// (PUT /v1/me/household)
	SwitchHousehold(ctx context.Context, request SwitchHouseholdRequestObject) (SwitchHouseholdResponseObject, error)
	// The user's passkeys
	// (GET /v1/me/passkeys)
	ListMyPasskeys(ctx context.Context, request ListMyPasskeysRequestObject) (ListMyPasskeysResponseObject, error)
	// Start adding a passkey
	// (POST /v1/me/passkeys/begin)
	BeginAddPasskey(ctx context.Context, request BeginAddPasskeyRequestObject) (BeginAddPasskeyResponseObject, error)
	// Store the new passkey
	// (POST /v1/me/passkeys/finish)
	FinishAddPasskey(ctx context.Context, request FinishAddPasskeyRequestObject) (FinishAddPasskeyResponseObject, error)
	// Remove a passkey (not the last one)
	// (DELETE /v1/me/passkeys/{passkeyId})
	RemoveMyPasskey(ctx context.Context, request RemoveMyPasskeyRequestObject) (RemoveMyPasskeyResponseObject, error)
	// The user's signed-in sessions
	// (GET /v1/me/sessions)
	ListMySessions(ctx context.Context, request ListMySessionsRequestObject) (ListMySessionsResponseObject, error)
	// Sign out one of the user's sessions
	// (DELETE /v1/me/sessions/{sessionId})
	RevokeMySession(ctx context.Context, request RevokeMySessionRequestObject) (RevokeMySessionResponseObject, error)
	// Build and contract versions, and the server clock
	// (GET /v1/meta)
	GetMeta(ctx context.Context, request GetMetaRequestObject) (GetMetaResponseObject, error)
	// The user's inbox, newest first, with the unread count
	// (GET /v1/notifications)
	ListNotifications(ctx context.Context, request ListNotificationsRequestObject) (ListNotificationsResponseObject, error)
	// The user's alert preferences (their own, else the system defaults)
	// (GET /v1/notifications/preferences)
	GetNotificationPreferences(ctx context.Context, request GetNotificationPreferencesRequestObject) (GetNotificationPreferencesResponseObject, error)
	// Change the user's alert preferences
	// (PUT /v1/notifications/preferences)
	SetNotificationPreferences(ctx context.Context, request SetNotificationPreferencesRequestObject) (SetNotificationPreferencesResponseObject, error)
	// Mark notifications read
	// (POST /v1/notifications/read)
	MarkNotificationsRead(ctx context.Context, request MarkNotificationsReadRequestObject) (MarkNotificationsReadResponseObject, error)
	// Disconnect Telegram
	// (DELETE /v1/notifications/telegram)
	DisconnectTelegram(ctx context.Context, request DisconnectTelegramRequestObject) (DisconnectTelegramResponseObject, error)
	// Whether the bot is available and this user is connected
	// (GET /v1/notifications/telegram)
	GetTelegramConnection(ctx context.Context, request GetTelegramConnectionRequestObject) (GetTelegramConnectionResponseObject, error)
	// Start connecting Telegram
	// (POST /v1/notifications/telegram/link)
	StartTelegramLink(ctx context.Context, request StartTelegramLinkRequestObject) (StartTelegramLinkResponseObject, error)
	// Send a test message to the user's Telegram
	// (POST /v1/notifications/telegram/test)
	TestTelegramConnection(ctx context.Context, request TestTelegramConnectionRequestObject) (TestTelegramConnectionResponseObject, error)
	// Whether the first admin still has to be claimed
	// (GET /v1/setup)
	GetSetupStatus(ctx context.Context, request GetSetupStatusRequestObject) (GetSetupStatusResponseObject, error)
	// Check the admin setup token and start enrolling the first admin's passkey
	// (POST /v1/setup/begin)
	BeginSetup(ctx context.Context, request BeginSetupRequestObject) (BeginSetupResponseObject, error)
	// Create the first admin and household, and sign in
	// (POST /v1/setup/finish)
	FinishSetup(ctx context.Context, request FinishSetupRequestObject) (FinishSetupResponseObject, error)
	// Changes to the household's synced rows since a cursor
	// (GET /v1/sync)
	GetSync(ctx context.Context, request GetSyncRequestObject) (GetSyncResponseObject, error)
	// Server-sent events that say "something changed, pull now"
	// (GET /v1/sync/events)
	GetSyncEvents(ctx context.Context, request GetSyncEventsRequestObject) (GetSyncEventsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

